import{_ as n,o as a,c as o,a2 as i}from"./chunks/framework.D5wUhsuj.js";const p=JSON.parse('{"title":"PhyAgentOS Documentation","description":"","frontmatter":{},"headers":[],"relativePath":"en/index.md","filePath":"en/index.md"}'),t={name:"en/index.md"};function r(s,e,l,d,c,u){return a(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="phyagentos-documentation" tabindex="-1">PhyAgentOS Documentation <a class="header-anchor" href="#phyagentos-documentation" aria-label="Permalink to &quot;PhyAgentOS Documentation&quot;">​</a></h1><p>Version: <strong>1.0.0</strong><br> Implementation baseline: <strong>Forge Skill binding, Query/Action/Session Tool API, AgentTask recovery, and version-scoped experience, 2026-08-30</strong></p><p>The PhyAgentOS team maintains this documentation for users, operators, and ecosystem developers. A feature is described as current only when it is supported by repository source, configuration schemas, and tests.</p><h2 id="core-manuals" tabindex="-1">Core manuals <a class="header-anchor" href="#core-manuals" aria-label="Permalink to &quot;Core manuals&quot;">​</a></h2><ol><li><a href="/docs/en/01-framework-introduction">Framework Introduction</a>: positioning, control-plane boundaries, execution/evidence/verdict separation, lifecycle, and implemented scope.</li><li><a href="/docs/en/02-user-manual">User Manual</a>: installation, provider and Forge configuration, task description, verification modes, artifacts, and troubleshooting.</li><li><a href="/docs/en/03-developer-manual">Developer Manual</a>: AgentTask, Tool API client, Skill Runtime, evidence, verifier, recovery, and testing.</li><li><a href="/docs/en/04-forge-configuration-reference">Forge Configuration Reference</a>: Forge Tool API, Resource Registry, evidence, verification, AgentTask, and embodiment fields.</li><li><a href="/docs/en/05-agent-experience-and-skill-evolution">Agent Experience and Skill Evolution</a>: Skill activation and attribution, episodes, Lesson clustering, Skill promotion, persistence, and guardrails.</li></ol><h2 id="focused-manuals" tabindex="-1">Focused manuals <a class="header-anchor" href="#focused-manuals" aria-label="Permalink to &quot;Focused manuals&quot;">​</a></h2><ul><li><a href="/docs/user_manual/README_en">Operations Manual</a></li><li><a href="/docs/user_manual/DOCKER_en">Docker Deployment Guide</a></li><li><a href="/docs/user_development_guide/README_en">Integration Development Guide</a></li><li><a href="/docs/user_development_guide/COMMUNICATION_en">Communication Architecture</a></li><li><a href="/docs/forge/README">Forge Tool API Integration Contract</a></li></ul><h2 id="runtime-and-compatibility-boundaries" tabindex="-1">Runtime and compatibility boundaries <a class="header-anchor" href="#runtime-and-compatibility-boundaries" aria-label="Permalink to &quot;Runtime and compatibility boundaries&quot;">​</a></h2><p>PAOS supports Forge Query, Action, and Session through <code>/tools</code> and <code>/invocations</code>. The Agent-side aggregate is AgentTask, while physical execution remains owned by Gateway ToolInvocation and ToolEndpoint. Skill Runtime manages manifest-v2 bundles and named Dora profiles; it is distinct from the removed Markdown queue Runtime. Existing evolution, experience, verification, and Agent workspace data are read in place. Registry downloads are explicit and digest-verified.</p>',9)])])}const g=n(t,[["render",r]]);export{p as __pageData,g as default};
